@startuml

class City {
  + Name : string
  + Inhabitants : int
}

class Attraction {
  + Name : string
  + Address : string
}

class GuidedTour {
  + Duration : string
  + NumberOfParticipants : int
}

class Person {
  + Name : string
}

class Visitor extends Person {}

class Guide extends Person {}

class Discount {
  + Amount : float
}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "0..*" -- "1" Guide
GuidedTour "0..*" -- "1..20" Visitor
GuidedTour "0..*" -- "0..*" Discount
Discount "1" -- "1" Visitor
Discount "1" -- "1" GuidedTour

@enduml

